// Obtener el registro actual de Notion
const registro = $input.item.json;

// Recuperar los campos necesarios
const id = registro.id;
const idea = registro.property_idea_tema;
const nombre = registro.property_nombre_destinatario;
const email = registro.property_email_destinatario;

// Acumular los errores encontrados
const errores = [];

// Validaciones obligatorias
if (!id || String(id).trim() === '') {
  errores.push('Falta el identificador de Notion');
}

if (!idea || String(idea).trim() === '') {
  errores.push('Falta la idea o tema');
}

if (!nombre || String(nombre).trim() === '') {
  errores.push('Falta el nombre del destinatario');
}

if (!email || String(email).trim() === '') {
  errores.push('Falta el correo electrónico');
} else {
  // Validación básica del formato del correo
  const formatoEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!formatoEmail.test(String(email).trim())) {
    errores.push('El correo electrónico tiene un formato inválido');
  }
}

// Determinar si la solicitud puede continuar
const esValido = errores.length === 0;

// Devolver los datos originales y el resultado
return {
  json: {
    ...registro,
    validacion: {
      es_valido: esValido,
      errores: errores,
      cantidad_errores: errores.length
    }
  }
};

const respuesta = $input.item.json;

const contenido = respuesta.output?.[0]?.content?.[0]?.text;

let datos = null;

// La IA devuelve la clasificación como texto JSON,
// por lo que debemos convertirla a objeto.
if (typeof contenido === 'string') {
  try {
    datos = JSON.parse(contenido);
  } catch (e) {
    datos = null;
  }
} else if (contenido && typeof contenido === 'object') {
  datos = contenido;
}

const categoriasValidas = [
  'Educativo',
  'Comercial',
  'Institucional'
];

const clasificacion = datos?.clasificacion;
const justificacion = datos?.justificacion;

const errores = [];

if (!categoriasValidas.includes(clasificacion)) {
  errores.push('La clasificación no es válida');
}

if (
  typeof justificacion !== 'string' ||
  justificacion.trim() === ''
) {
  errores.push('Falta la justificación');
}

return {
  json: {
    ...respuesta,
    clasificacion_validada: {
      es_valida: errores.length === 0,
      clasificacion: clasificacion ?? null,
      justificacion: justificacion ?? null,
      errores
    }
  }
};

// Obtener la clasificación validada previamente
const categoria = $('A-09 | Datos | Preparar clasificación')
  .item.json.clasificacion;

// Obtener todos los conocimientos activos recuperados de Notion
const conocimientos = $input.all().map(item => item.json);

// Seleccionar conocimientos generales y de la categoría solicitada
const seleccionados = conocimientos
  .filter(k =>
    k.property_activo === true &&
    (
      k.property_categoria === 'General' ||
      k.property_categoria === categoria
    )
  )
  .sort((a, b) =>
    a.property_tema.localeCompare(
      b.property_tema,
      'es',
      { numeric: true }
    )
  );

// Preparar el contexto que recibirá OpenAI
const contexto = seleccionados.map(k => ({
  tema: k.property_tema,
  tipo: k.property_tipo,
  categoria: k.property_categoria,
  contenido: k.property_contenido
}));

return [{
  json: {
    categoria,
    cantidad_conocimientos: contexto.length,
    conocimientos: contexto,
    contexto_ia: contexto.map(k =>
      `[${k.tema}] (${k.tipo} / ${k.categoria})\n${k.contenido}`
    ).join('\n\n')
  }
}];

