const respuesta = $input.item.json;

const contenido = respuesta.output?.[0]?.content?.[0]?.text;

let borrador = null;

// La IA devuelve el borrador como texto JSON;
// hay que convertirlo a objeto antes de validarlo.
if (typeof contenido === 'string') {
  try {
    borrador = JSON.parse(contenido);
  } catch (e) {
    borrador = null;
  }
} else if (contenido && typeof contenido === 'object') {
  borrador = contenido;
}

const errores = [];
const resultadosValidos = ['Generado', 'No generado'];

if (!borrador || typeof borrador !== 'object') {
  errores.push('La IA no devolvió un objeto JSON válido');
}

const resultado = borrador?.resultado;
const asunto = borrador?.asunto;
const cuerpo = borrador?.cuerpo;
const fuentes = borrador?.fuentes;

if (!resultadosValidos.includes(resultado)) {
  errores.push('Resultado no permitido');
}

if (!Array.isArray(fuentes)) {
  errores.push('Las fuentes deben ser un arreglo');
}

if (resultado === 'Generado') {
  if (typeof asunto !== 'string' || !asunto.trim()) {
    errores.push('Falta el asunto');
  }

  if (typeof cuerpo !== 'string' || !cuerpo.trim()) {
    errores.push('Falta el cuerpo');
  }

  if (!Array.isArray(fuentes) || fuentes.length === 0) {
    errores.push('No se declararon fuentes');
  }
}

if (resultado === 'No generado') {
  if (asunto !== '' || cuerpo !== '' ||
      !Array.isArray(fuentes) || fuentes.length !== 0) {
    errores.push('La respuesta No generado contiene datos inesperados');
  }
}

// Verificar que las fuentes declaradas estén entre las autorizadas
const conocimientos = $('A-12 | Conocimiento | Filtrar por categoría')
  .first().json.conocimientos;

const fuentesAutorizadas = conocimientos.map(k =>
  k.tema.match(/^K\d+/)?.[0]
).filter(Boolean);

if (Array.isArray(fuentes)) {
  for (const fuente of fuentes) {
    if (!fuentesAutorizadas.includes(fuente)) {
      errores.push(`Fuente no autorizada: ${fuente}`);
    }
  }
}

return {
  json: {
    ...respuesta,
    borrador_validado: {
      es_valido: errores.length === 0,
      resultado: resultado ?? null,
      asunto: asunto ?? '',
      cuerpo: cuerpo ?? '',
      fuentes: Array.isArray(fuentes) ? fuentes : [],
      errores
    }
  }
};

